ALTER TABLE users ADD COLUMN banned_at INTEGER;
ALTER TABLE users ADD COLUMN deleted_at INTEGER;
CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS request_events (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_request_events_time ON request_events(created_at);
CREATE TABLE IF NOT EXISTS account_deletion_events (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_presence (user_id TEXT PRIMARY KEY,last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS support_tickets (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);